import{_ as t,o as s,a as e,b as l}from"./app.DKoEZOcr.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"Memory矢量计算","link":"/api/SIMD-API/c_api/vector_compute/vector_compute"},{"text":"掩码操作","link":"/api/SIMD-API/c_api/vector_compute/vector_mask_config/vector_mask_config"},{"text":"asc_set_vector_mask","link":"/api/SIMD-API/c_api/vector_compute/vector_mask_config/asc_set_vector_mask"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/vector_compute/vector_mask_config/asc_set_vector_mask.md","filePath":"api/SIMD-API/c_api/vector_compute/vector_mask_config/asc_set_vector_mask.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"流水类型","slug":"流水类型","link":"#流水类型"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787909275000}'),i={name:"api/SIMD-API/c_api/vector_compute/vector_mask_config/asc_set_vector_mask.md"};function _(c,a,d,r,o,n){return s(),e("div",null,[...a[0]||(a[0]=[l(`<div><article class="markdown-body"><h1>asc_set_vector_mask</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>本API用于设置Mask值。某些矢量计算接口需要提前设置Mask，用于指示哪些数据参与计算。 单独使用该API时可引入<code>c_api/vector_compute/compute/vector_mask_config.h</code>，整体使用C API时可引入<code>c_api/asc_simd.h</code>。</p><div data-filter="950"><ul><li>针对Ascend 950PR/Ascend 950DT：该接口通常用于VF场景外设置掩码寄存器，配合Reg矢量计算接口使用。</li></ul></div><div data-filter="A3,910b"><ul><li>针对如下产品型号： <div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li></ul></div> 该接口支持Normal模式和Counter模式。使用前需要先调用<a href="asc_set_mask_count.html">asc_set_mask_count</a>或<a href="asc_set_mask_norm.html">asc_set_mask_norm</a>设置Mask模式。在不同的模式下Mask的含义如下：<br>Normal模式用于高维切分计算类API。该模式下，Mask参数用来控制单次迭代内参与计算的元素，可以按位控制哪些元素参与计算：bit位的值为1表示参与计算，0表示不参与。Mask参数分为mask_high（高位Mask）和mask_low（低位Mask）。参数取值范围和操作数的数据类型有关，数据类型不同，每次迭代内能够处理的元素个数最大值不同。当操作数为16位时，mask_high，mask_low∈[0, 2^64-1]，并且不同时为0；当操作数为32位时，mask_high为0，mask_low∈(0, 2^64-1]；当操作数为64位时，mask_high为0，mask_low∈(0, 2^32-1]。<br>Counter模式用于前n个数据计算类API。该模式下，Mask参数用于控制整个计算过程中参与计算的元素个数。前n个数据计算类接口中已经实现了Normal模式和Counter模式的转换，用户不需要自行设置。</li></ul></div><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_set_vector_mask</span><span class="p">(</span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">mask_high</span><span class="p">,</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">mask_low</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><div data-filter="950"><p><strong>表</strong> 参数说明（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>）</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>mask_high</td><td>输入</td><td>高64位Mask值。</td></tr><tr><td>mask_low</td><td>输入</td><td>低64位Mask值。</td></tr></tbody></table></div><div data-filter="A3,910b"><p><strong>表</strong> 参数说明（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>）</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>mask_high</td><td>输入</td><td>Normal模式：高位mask值。<br>Counter模式：需要置0，本入参不生效。</td></tr><tr><td>mask_low</td><td>输入</td><td>Normal模式：低位mask值。<br>Counter模式：整个矢量计算过程中，参与计算的元素个数。</td></tr></tbody></table></div><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="流水类型">流水类型<a class="header-anchor" href="#流水类型">​</a></h2><p>PIPE_S</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><div data-filter="950"><ul><li>针对Ascend 950PR/Ascend 950DT：该接口用于在VF场景外设置掩码寄存器。在Reg矢量计算配置时，通过<a href="../../reg_compute/reg_mask/asc_get_mask_spr.html">asc_get_mask_spr</a>接口中的<code>asc_get_mask_spr_b16</code>或<code>asc_get_mask_spr_b32</code>配合获取掩码寄存器的值。更推荐用户使用VF场景内<a href="../../reg_compute/reg_mask/reg_mask.html">掩码寄存器操作</a>章节中的接口完成Reg矢量计算掩码配置。</li></ul></div><div data-filter="A3,910b"><ul><li>针对如下产品型号： <div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li></ul></div> 需先调用<a href="asc_set_mask_count.html">asc_set_mask_count</a>或<a href="asc_set_mask_norm.html">asc_set_mask_norm</a>设置Mask模式。</li></ul></div><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div data-filter="950"><ul><li>针对Ascend 950PR/Ascend 950DT： 请参考<a href="../../reg_compute/reg_mask/asc_get_mask_spr.html#%E8%B0%83%E7%94%A8%E7%A4%BA%E4%BE%8B">asc_get_mask_spr</a>，该示例中<code>asc_get_mask_spr_b16</code>或<code>asc_get_mask_spr_b32</code>读取的掩码值即为<code>asc_set_vector_mask</code>设置值，用户可在VF外设置。</li></ul></div><div data-filter="A3,910b"><ul><li>针对如下产品型号： <div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li></ul></div> 请参考<a href="asc_set_mask_count.html#%E8%B0%83%E7%94%A8%E7%A4%BA%E4%BE%8B">asc_set_mask_count</a>或<a href="asc_set_mask_norm.html#%E8%B0%83%E7%94%A8%E7%A4%BA%E4%BE%8B">asc_set_mask_norm</a>。</li></ul></div></article></div>`,1)])])}const m=t(i,[["render",_]]);export{p as __pageData,m as default};
